  ["c71e8f1662fc5813"] = { "Di nuovo questi tre?", "." },
  ["c7222432e5c1fe8f"] = { "Una sola sacerdotessa elfa della notte è stata troppo per te?", "." },
  ["c7251d5304203feb"] = { "Che tempo magnifico abbiamo qui, non trovi?", "." },
  ["c7342fc4a0add1c9"] = { "Una voce limpida si leva dall'interno della pietra...\n\nDov'è il tuo Medaglione della Ricezione, piccola creatura? Non puoi parlare con un duca senza una prova del tuo titolo...", "." },
  ["c745c221b5060cce"] = { "Le difese della torre sono al punto più debole, adesso. Pattugliatori, sentinelle, vedette e persino Gallywix in persona sono tutti infetti e molto vulnerabili alle tue abilità e ai tuoi attacchi speciali.\n\nVoglio vederti entrare in quella torre e, quando ne uscirai, voglio vederti <coperto/coperta> del sangue dei tuoi nemici, con la testa del gran caposquadra Puzik Gallywix fra le mani e l'ultimo di quel veleno nello zaino. Porta ciò che recuperi a Shenthul. Lui saprà cosa fare... spero.", "." },
  ["c74a88d37cc645e4"] = { "%s: innesco tra 3 secondi!", "." },
  ["c751a56b3af86718"] = { "Ah, il buon vecchio ⟦Brandur Ironhammer=Brandur Fermartello⟧. Non c'è dubbio che ti darà la guida che cerchi, <ragazzo/ragazza>. Lo troverai nella Hall of Mysteries, a nord dei cancelli di ⟦Ironforge=Forgiardente⟧.", "." },
  ["c766eccd6888dad3"] = { "Ci sono Tuberi di Foglia Blu in questa trincea! È oro che aspetta solo di essere estratto, te lo dico io!", "." },
  ["c768d5273273710f"] = { "Sei <tornato/tornata> ad aiutare Kum'isha, {race}? Non preoccuparti, la fitta che senti alla bocca dello stomaco è solo la tua forza di volontà che crolla.\n\nPer fortuna, per questa raccolta la forza di volontà non ti servirà. Non ho dubbi che apprezzerai i ninnoli che ti farò trovare al tuo ritorno con l'oggetto.", "." },
  ["c76e43f60a3d89ab"] = { "Hai uno scrigno del tesoro? Fammi vedere! D'accordo, cerca Zando'zan nel Cleft of Shadow. Per trovarlo, cerca il tunnel che scende nel Varcolargo.", "." },
  ["c770b7f6a21e433c"] = { "%s lancia un grido trionfante.", "." },
  ["c77505da274c7cbc"] = { "TRAFIGGETELI, FRATELLI!", "." },
  ["c780afe294966e1d"] = { "Si trova nel ⟦Trade District=Quartiere del Commercio⟧, <cittadino/cittadina>. È quasi dritto davanti all'ingresso di ⟦Stormwind=Roccavento⟧.", "." },
  ["c785cf3003055b73"] = { "Ti occupi di alchimia? Anch'io. Forse puoi insegnarmi quello che sai...", "." },
  ["c78f657f01008e83"] = { "Spiriti della foresta, c'è bisogno di voi! Affrettatevi verso la ⟦Charred Vale=Valle Bruciata⟧!", "." },
  ["c79de958b2d3a532"] = { "Ecco fatto, {name}. La Pergamena è riparata! Evviva!", "." },
  ["c79ea1ef619dcea9"] = { "Salve, giovane {class}. Sei qui per portarmi un carico di peacebloom? Li raccogliamo per preparare pozioni ed elisir per lo sforzo bellico di ⟦Ahn'Qiraj=Ahn'qiraj⟧. Per quanto sia tragico essere costretti a questa guerra, le conseguenze saranno ancora più terribili se non ci prepariamo a dovere.\n\nL'⟦Horde=Orda⟧ mi ha incaricato di raccogliere $2020w peacebloom, e finora ne abbiamo messi insieme $2021w. Se ne hai la possibilità, per favore raccogline quanti più puoi e riportali qui da me.", "." },
  ["c7bc02be18b51221"] = { "Ehi, ma che bel vestito che hai!", "." },
  ["c7c971d34065dafb"] = { "Lumurk aprire questa scatola facile!", "." },
  ["c7d3d2fb50189833"] = { "Mi spiace, ma hai raggiunto il limite di quello che posso insegnarti. Se vuoi imparare di più, va' da Telonis, nella ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧ di Darnassus. Dicono che abbia molto talento.", "." },
  ["c7d5b60846fddf14"] = { "Qualcuno vuole dare una bella casa al mio gattino?", "." },
  ["c7d7442731d0684d"] = { "Ben fatto, ben fatto, {name}. Vedo che abbiamo fatto bene a decidere di addestrarti. Le tue prestazioni di certo non deludono.\n\nNon ho alcuna remora a mostrarti come controllare la succube che hai appena vincolato. Osserva attentamente.", "." },
  ["c7d96d2cc269fbd9"] = { "Sì, offro addestramento. Ma non costa poco.", "." },
  ["c7db5bcc03d062cc"] = { "L'anziana Totem Fulgido si trova in compagnia dei goblin di ⟦Ratchet=Porto Paranco⟧, sulla costa delle ⟦Barrens=Savane⟧.", "." },
  ["c7de37be1dcb7d2b"] = { "Ho... ho fallito, {name}. Il signore di Rocc... Il signore di ⟦Blackrock=Roccianera⟧ è troppo potente. Ha consumato la mia energia con... con facilità. Mi sto trasformando... io... uccidimi... devi... devi uccidermi.", "." },
  ["c7e26d2ca6b87cb8"] = { "Hai fatto una scoperta straordinaria. Mi piacerebbe avere l'occasione di esaminare tutti gli esperimenti falliti.", "." },
  ["c7e414897be09dd7"] = { "Trovi Aldwin Laughlin al Visitor's Center di ⟦Stormwind=Roccavento⟧, nel ⟦Trade District=Quartiere del Commercio⟧.", "." },
  ["c7e707f49918e029"] = { "%s comincia a emettere strani grugniti. La ⟦Tear of the Moons=Lacrima delle Lune⟧ cade a terra e va in frantumi.", "." },
  ["c7e822d4fec53a9f"] = { "Vattene da qui, Tobias, sei libero!", "." },
  ["c7e97f2077120780"] = { "Non dimenticare di prendere un po' di ⟦Flame in a Bottle=Fiamma in Bottiglia⟧ dalla cassa qui. Ti servirà per distruggere la loro tenda di comando.", "." },
  ["c7f2be9997224678"] = { "Lucan Cordell ha una piccola bottega sul canale, vicino alle ⟦Stockade=Segrete di Roccavento⟧. Di sicuro saprà insegnarti l'arte dell'incantamento.", "." },
  ["c7f5270188d2c319"] = { "⟦Icy Scale Bracers=Bracciali di Scaglie Ghiacciate⟧.", "." },
  ["c7fbf269aa7dc1a8"] = { "Non posso, Vaelastrasz! Ci sarà pure qualcosa per guarirti!", "." },
  ["c7fdae7ceb58aebe"] = { "Ti ringrazio, {name}. La tua dedizione alla mia supplica dà pace allo spirito della mia sposa perduta, e per questo non potrò mai ripagarti abbastanza.\n\nNon posso dire che il mio odio per i verrospini cesserà mai, ma per ora è placato.\n\nOra devo cominciare a ricostruire la mia vita.", "." },
